import argparse

from taf.ul.bts_kpi_report_generator import bts_kpi_report_generator

parser_convert = argparse.ArgumentParser(description='Parameters: convert_xml_yaml')
parser_convert.add_argument('-p', '--path_xml', dest='path_xml', type=str, required=True, help='path to XML file with NIDD')


def convert_xml_yaml():
    arguments = parser_convert.parse_args()
    bts_kpi_report_generator.convert_xml_yaml(arguments.path_xml)
